create extension if not exists "uuid-ossp";
create type public.user_role as enum ('admin','passenger');
create type public.flight_status as enum ('Scheduled','Check-in Open','Check-in Closed','Boarding','Final Call','Departed','Landed','Delayed','Cancelled');
create table if not exists public.profiles (id uuid primary key references auth.users(id) on delete cascade, full_name text not null, email text not null unique, role public.user_role not null default 'passenger', phone text, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.airports (id uuid primary key default uuid_generate_v4(), code text unique not null, name text not null, city text not null, country text not null, created_at timestamptz default now());
create table if not exists public.terminals (id uuid primary key default uuid_generate_v4(), airport_id uuid references public.airports(id), name text not null, status text default 'Operational');
create table if not exists public.gates (id uuid primary key default uuid_generate_v4(), terminal_id uuid references public.terminals(id), code text not null, status text default 'Available', unique(terminal_id,code));
create table if not exists public.airlines (id uuid primary key default uuid_generate_v4(), name text not null, code text unique not null);
create table if not exists public.aircraft (id uuid primary key default uuid_generate_v4(), airline_id uuid references public.airlines(id), model text not null, seat_capacity integer not null check(seat_capacity>0));
create table if not exists public.flights (id uuid primary key default uuid_generate_v4(), flight_number text not null, airline_id uuid references public.airlines(id), origin_airport_id uuid references public.airports(id), destination_airport_id uuid references public.airports(id), terminal_id uuid references public.terminals(id), gate_id uuid references public.gates(id), aircraft_id uuid references public.aircraft(id), departure_at timestamptz not null, arrival_at timestamptz, estimated_departure_at timestamptz, status public.flight_status not null default 'Scheduled', delay_reason text, created_at timestamptz default now(), updated_at timestamptz default now());
create table if not exists public.bookings (id uuid primary key default uuid_generate_v4(), pnr text unique not null, user_id uuid references public.profiles(id), flight_id uuid references public.flights(id), status text not null default 'Confirmed', total_amount numeric(12,2) default 0, created_at timestamptz default now(), updated_at timestamptz default now());
create table if not exists public.seats (id uuid primary key default uuid_generate_v4(), flight_id uuid references public.flights(id) on delete cascade, seat_number text not null, class text not null default 'Economy', unique(flight_id,seat_number));
create table if not exists public.booking_passengers (id uuid primary key default uuid_generate_v4(), booking_id uuid references public.bookings(id) on delete cascade, full_name text not null, seat_id uuid references public.seats(id), ticket_number text unique not null);
create table if not exists public.check_ins (id uuid primary key default uuid_generate_v4(), booking_id uuid unique references public.bookings(id), checked_in_at timestamptz default now(), status text default 'Completed');
create table if not exists public.baggage (id uuid primary key default uuid_generate_v4(), booking_id uuid references public.bookings(id), tag_number text unique not null, status text not null default 'Baggage Accepted', updated_at timestamptz default now());
create table if not exists public.notifications (id uuid primary key default uuid_generate_v4(), user_id uuid references public.profiles(id) on delete cascade, title text not null, body text not null, read_at timestamptz, created_at timestamptz default now());
create table if not exists public.announcements (id uuid primary key default uuid_generate_v4(), title text not null, body text not null, flight_id uuid references public.flights(id), created_by uuid references public.profiles(id), created_at timestamptz default now());
create table if not exists public.audit_logs (id uuid primary key default uuid_generate_v4(), actor_id uuid references public.profiles(id), action text not null, entity_type text not null, entity_id uuid, metadata jsonb default '{}'::jsonb, created_at timestamptz default now());
create index if not exists flights_departure_idx on public.flights(departure_at,status); create index if not exists bookings_user_idx on public.bookings(user_id); create index if not exists notifications_user_idx on public.notifications(user_id,created_at desc);
alter table public.profiles enable row level security; alter table public.bookings enable row level security; alter table public.notifications enable row level security;
create policy "users read own profile" on public.profiles for select using (auth.uid()=id); create policy "users read own bookings" on public.bookings for select using (auth.uid()=user_id); create policy "users read own notifications" on public.notifications for select using (auth.uid()=user_id);
